import {
  Body,
  Column,
  Container,
  Head,
  Hr,
  Html,
  Preview,
  Row,
  Section,
  Text,
} from "@react-email/components";
import type { DealsByOrigin, ScoredDeal } from "@/lib/deals/scoreAndFilter";
import { buildDealDigestCard } from "@/lib/deals/dealTravelPresentation";

type Props = {
  deals: DealsByOrigin;
  generatedAt: string;
};

const ACCENT = "#defd4e";
const CARD = "#161616";
const MUTED = "#a3a3a3";
const LABEL = "#737373";
const BODY_TEXT = "#fafafa";
const BORDER = "#2a2a2a";

const fontStack =
  "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif";

const lab = {
  margin: "0 0 4px 0",
  fontSize: "10px",
  lineHeight: "14px",
  letterSpacing: "0.1em",
  textTransform: "uppercase" as const,
  color: LABEL,
  fontWeight: 600,
};

function isEuropeContinent(label: string): boolean {
  return label.trim().toLowerCase() === "europe";
}

function selectTopDealsToday(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter((d) => d.hubFare.stops === 0 && d.scoreResult.score >= 75)
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 5);
}

function selectIntraEuropeTop(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter(
      (d) =>
        isEuropeContinent(d.hubFare.hub.originContinent) &&
        isEuropeContinent(d.hubFare.destinationContinent)
    )
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 10);
}

function selectOutsideEuropeTop(allDeals: ScoredDeal[]): ScoredDeal[] {
  return [...allDeals]
    .filter(
      (d) =>
        isEuropeContinent(d.hubFare.hub.originContinent) &&
        d.hubFare.destinationContinent.trim() !== "" &&
        !isEuropeContinent(d.hubFare.destinationContinent)
    )
    .sort((a, b) => a.hubFare.price - b.hubFare.price)
    .slice(0, 10);
}

function DigestDealCard({
  deal,
  index,
  sectionLabel,
}: {
  deal: ScoredDeal;
  index: number;
  sectionLabel?: string;
}) {
  const m = buildDealDigestCard(deal);

  const metaFooter = [m.isFeatured ? "Featured pick" : null, sectionLabel].filter(Boolean);

  return (
    <Section
      style={{
        backgroundColor: CARD,
        borderRadius: "16px",
        padding: "26px 24px 28px",
        marginTop: index === 0 ? "0" : "28px",
      }}
    >
      <Row>
        <Column style={{ width: "52%", verticalAlign: "top", paddingRight: "16px" }}>
          <Text style={{ ...lab, margin: "0 0 8px 0" }}>Destination</Text>
          <Text
            style={{
              margin: "0",
              fontSize: "34px",
              lineHeight: "1.12",
              fontWeight: 700,
              color: BODY_TEXT,
              letterSpacing: "-0.02em",
            }}
          >
            {m.destinationCity}
          </Text>
        </Column>
        <Column style={{ width: "48%", verticalAlign: "top", textAlign: "right" }}>
          <Text style={{ ...lab, margin: "0 0 8px 0", textAlign: "right" }}>Starting at</Text>
          <Text
            style={{
              margin: "0",
              fontSize: "52px",
              lineHeight: "1",
              fontWeight: 800,
              color: "#ffffff",
              letterSpacing: "-0.03em",
            }}
          >
            ${m.price}
          </Text>
        </Column>
      </Row>

      <Text style={{ ...lab, margin: "22px 0 6px 0" }}>From / route</Text>
      <Text
        style={{
          margin: "0 0 18px 0",
          fontSize: "15px",
          lineHeight: "1.45",
          fontWeight: 600,
          color: "#ececec",
        }}
      >
        From {m.originCity}{" "}
        <span style={{ color: MUTED, fontWeight: 500 }}>
          ({m.originCode} → {m.destinationCode})
        </span>
      </Text>

      <Text
        style={{
          margin: "0 0 22px 0",
          fontSize: "13px",
          lineHeight: "1.5",
          color: MUTED,
        }}
      >
        {m.flightMetaLine}
      </Text>

      <Hr style={{ borderColor: BORDER, borderWidth: "1px", margin: "0 0 20px 0" }} />

      <Row>
        <Column style={{ width: "50%", verticalAlign: "top", paddingRight: "14px" }}>
          <Text style={{ ...lab, margin: "0 0 8px 0" }}>Dates</Text>
          <Text
            style={{
              margin: "0",
              fontSize: "15px",
              lineHeight: "1.35",
              fontWeight: 600,
              color: BODY_TEXT,
            }}
          >
            {m.compactTripDates ?? "—"}
          </Text>
        </Column>
        <Column style={{ width: "50%", verticalAlign: "top", paddingLeft: "14px" }}>
          <Text style={{ ...lab, margin: "0 0 8px 0" }}>Value score</Text>
          <Text
            style={{
              margin: "0",
              fontSize: "15px",
              lineHeight: "1.35",
              fontWeight: 600,
              color: BODY_TEXT,
            }}
          >
            {m.score}/100
          </Text>
        </Column>
      </Row>

      <Text
        style={{
          margin: "22px 0 0 0",
          fontSize: "13px",
          lineHeight: "1.55",
          color: "#d4d4d4",
        }}
      >
        <span style={{ fontWeight: 700, color: BODY_TEXT }}>Why this surfaced:</span>{" "}
        {m.whyBrief}
      </Text>

      {m.showEarlyDataNote ? (
        <Text
          style={{
            margin: "10px 0 0 0",
            fontSize: "11px",
            lineHeight: "1.45",
            color: "#64748b",
          }}
        >
          Limited history on this route — treat pricing as indicative.
        </Text>
      ) : null}

      {metaFooter.length > 0 ? (
        <Text
          style={{
            margin: "16px 0 0 0",
            paddingTop: "14px",
            borderTop: `1px solid ${BORDER}`,
            fontSize: "10px",
            letterSpacing: "0.06em",
            color: "#525252",
          }}
        >
          {metaFooter.join(" · ")}
        </Text>
      ) : null}
    </Section>
  );
}

function HighlightSection({
  title,
  subtitle,
  deals,
  cardKeyPrefix,
}: {
  title: string;
  subtitle: string;
  deals: ScoredDeal[];
  cardKeyPrefix: string;
}) {
  if (deals.length === 0) return null;

  return (
    <Section
      style={{
        backgroundColor: "#111111",
        borderRadius: "18px",
        padding: "28px 24px 32px",
        margin: "0 0 28px 0",
      }}
    >
      <Text
        style={{
          margin: "0 0 6px 0",
          fontSize: "10px",
          letterSpacing: "0.14em",
          textTransform: "uppercase",
          color: "#525252",
          fontWeight: 600,
        }}
      >
        {title}
      </Text>
      <Text
        style={{
          margin: "0 0 26px 0",
          fontSize: "13px",
          lineHeight: "1.5",
          color: MUTED,
        }}
      >
        {subtitle}
      </Text>
      {deals.map((deal, index) => (
        <DigestDealCard
          key={`${cardKeyPrefix}-${deal.hubFare.hub.origin}-${deal.hubFare.destination}-${deal.hubFare.departureDate}-${index}`}
          deal={deal}
          index={index}
          sectionLabel={title}
        />
      ))}
    </Section>
  );
}

export default function DealsDigest({ deals, generatedAt }: Props) {
  const flatDeals = Object.values(deals).flat();
  const topDealsToday = selectTopDealsToday(flatDeals);
  const intraEuropeDeals = selectIntraEuropeTop(flatDeals);
  const outsideEuropeDeals = selectOutsideEuropeTop(flatDeals);

  return (
    <Html>
      <Head />
      <Preview>Best Escapes This Week</Preview>
      <Body
        style={{
          backgroundColor: "#0a0a0a",
          margin: "0",
          padding: "48px 24px",
          color: "#e5e5e5",
          fontFamily: fontStack,
        }}
      >
        <Container
          style={{
            maxWidth: "640px",
            margin: "0 auto",
            backgroundColor: "#0a0a0a",
          }}
        >
          <Text
            style={{
              margin: "0 0 10px 0",
              fontSize: "11px",
              letterSpacing: "0.16em",
              textTransform: "uppercase",
              color: "#525252",
              fontWeight: 600,
            }}
          >
            Deal digest
          </Text>
          <Text
            style={{
              margin: "0 0 12px 0",
              color: ACCENT,
              fontSize: "30px",
              lineHeight: "1.15",
              letterSpacing: "-0.02em",
              fontWeight: 700,
            }}
          >
            Best Escapes This Week
          </Text>
          <Text
            style={{
              margin: "0 0 36px 0",
              fontSize: "14px",
              lineHeight: "1.5",
              color: MUTED,
            }}
          >
            Surfaced from major European hubs · {generatedAt}
          </Text>

          {topDealsToday.length > 0 ? (
            <Section style={{ margin: "0 0 32px 0" }}>
              <Text
                style={{
                  margin: "0 0 6px 0",
                  fontSize: "10px",
                  letterSpacing: "0.14em",
                  textTransform: "uppercase",
                  color: "#525252",
                  fontWeight: 600,
                }}
              >
                Top Deals Today
              </Text>
              <Text
                style={{
                  margin: "0 0 22px 0",
                  fontSize: "13px",
                  lineHeight: "1.5",
                  color: MUTED,
                }}
              >
                Best nonstop fares across European hubs right now
              </Text>

              {topDealsToday.map((deal, index) => (
                <DigestDealCard
                  key={`top-${deal.hubFare.hub.origin}-${deal.hubFare.destination}-${deal.hubFare.departureDate}-${index}`}
                  deal={deal}
                  index={index}
                />
              ))}
            </Section>
          ) : null}

          <Section style={{ margin: "8px 0 28px 0", borderTop: `1px solid ${BORDER}` }} />

          <HighlightSection
            title="Within Europe"
            subtitle="Top genuine deals between European hubs (by price)"
            deals={intraEuropeDeals}
            cardKeyPrefix="intra"
          />

          <HighlightSection
            title="Beyond Europe"
            subtitle="Long-haul picks from European hubs (by price)"
            deals={outsideEuropeDeals}
            cardKeyPrefix="outside"
          />

          <Text
            style={{
              margin: "40px 0 0 0",
              fontSize: "12px",
              color: "#404040",
            }}
          >
            Flight Deal Alerts · Built by Sam
          </Text>
        </Container>
      </Body>
    </Html>
  );
}
